<?php if($kind!=='properties'): ?><select class="form-select" name="status" aria-label="Record Status"><option value="">All statuses</option><?php foreach($kind==='customers'?$options['customerStatuses']:$options['listingStatuses']as$status): ?><option value="<?= esc($status,'attr') ?>" <?= $filters['status']===$status?'selected':'' ?>><?= esc($status==='unlisted'?'Unpublished':ucwords(str_replace('_',' ',$status))) ?></option><?php endforeach ?></select><?php endif ?>
<?php if($kind==='resale'): ?><select class="form-select" name="method" aria-label="Selling Method"><option value="">All selling methods</option><?php foreach(['self_sell','shalimar_agent','authorized_agency']as$method): ?><option value="<?= $method ?>" <?= $filters['method']===$method?'selected':'' ?>><?= ar_method($method) ?></option><?php endforeach ?></select><?php endif ?>
<?php foreach(['customer','property']as$relation):if($filters[$relation]!==null): ?><input type="hidden" name="<?= $relation ?>" value="<?= $filters[$relation] ?>"><?php endif;endforeach ?>
<select class="form-select" name="per_page" aria-label="Rows per page"><?php foreach([10,25,50,100]as$amount): ?><option value="<?= $amount ?>" <?= $size===$amount?'selected':'' ?>><?= $amount ?> rows</option><?php endforeach ?></select><button class="btn btn-primary" type="submit">Apply</button><a class="btn btn-outline-secondary" href="<?= esc($baseUrl,'attr') ?>">Clear</a></div></form>
